const __pageData = JSON.parse('{"title":"Maven依赖管理与生命周期","description":"在 pom.xml 里配置依赖与排除依赖（含到 mvnrepository 搜坐标、刷新与联网两条注意事项），读懂 Maven 三套生命周期与阶段顺序、五个常用阶段的含义，以及 IDEA 面板双击与命令行两种执行方式，附本机实测的构建输出与报错","frontmatter":{"title":"Maven依赖管理与生命周期","published":"2026-09-29T00:00:00.000Z","description":"在 pom.xml 里配置依赖与排除依赖（含到 mvnrepository 搜坐标、刷新与联网两条注意事项），读懂 Maven 三套生命周期与阶段顺序、五个常用阶段的含义，以及 IDEA 面板双击与命令行两种执行方式，附本机实测的构建输出与报错","tags":["JavaWeb","Maven","后端"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-26-maven-dependency-lifecycle.webp","order":26,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/26-Maven依赖管理与生命周期.md","filePath":"posts/学习文档/JavaWeb学习笔记/26-Maven依赖管理与生命周期.md"}');
